class Solution {
    public int maximumDifference(int[] nums){
        int minimum=nums[0],answer=-1;
        for(int i=1;i<nums.length;i++){
            if(nums[i]>minimum)answer=Math.max(answer,nums[i]-minimum);
            minimum=Math.min(minimum,nums[i]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumDifference(nums:IntArray):Int{
        var minimum=nums[0];
        var answer=-1;
        for(i in 1 until nums.size){
            if(nums[i]>minimum)answer=maxOf(answer,nums[i]-minimum);
            minimum=minOf(minimum,nums[i])
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int maximumDifference(vector<int>& nums){
        int minimum=nums[0],answer=-1;
        for(int i=1;i<(int)nums.size();++i){
            if(nums[i]>minimum)answer=max(answer,nums[i]-minimum);
            minimum=min(minimum,nums[i]);
        }
        return answer;
    }
};
